    public static void main(String[] args) throws Exception {
        FastScanner fs=new FastScanner(); int T=fs.nextInt();
        while(T-->0){
            int N=fs.nextInt(); TreeMap<Integer,Integer> freq=new TreeMap<>();
            for(int i=0;i<N;i++){int x=fs.nextInt(); freq.put(x,freq.getOrDefault(x,0)+1);}
            boolean first=true; for(int x:freq.keySet()){if(!first)System.out.print(" ");System.out.print(x);first=false;}System.out.println();
