import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st;
        String next() throws Exception {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() throws Exception { return Integer.parseInt(next()); }
        long nextLong() throws Exception { return Long.parseLong(next()); }
    }
    public static void main(String[] args) throws Exception { FastScanner fs=new FastScanner(); int T=fs.nextInt(); while(T-->0){int N=fs.nextInt(),len=2*N;HashMap<Long,Integer>m=new HashMap<>();boolean ok=true;for(int i=0;i<len;i++){long x=fs.nextLong();int c=m.getOrDefault(x,0)+1;m.put(x,c);if(c>2)ok=false;}System.out.println(ok?"Yes":"No");}}
}
